import{_ as e,o as i,c as t,a0 as s}from"./chunks/framework.bcCluOOn.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function l(o,a,d,p,r,h){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Getting started with AAYU is extremely fast. Since AAYU&#39;s compiler and CLI are distributed via PyPI, you can install it globally using <code>pip</code>.</p><h2 id="_1-install-via-pip" tabindex="-1">1. Install via Pip <a class="header-anchor" href="#_1-install-via-pip" aria-label="Permalink to &quot;1. Install via Pip&quot;">​</a></h2><p>Open your terminal and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aayu-lang</span></span></code></pre></div><p>Verify that AAYU is installed by checking its version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aayu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="_2-install-the-vs-code-extension" tabindex="-1">2. Install the VS Code Extension <a class="header-anchor" href="#_2-install-the-vs-code-extension" aria-label="Permalink to &quot;2. Install the VS Code Extension&quot;">​</a></h2><p>For the best AAYU editing experience, install the AAYU VS Code extension from the Visual Studio Marketplace once it is published.</p><ul><li>Search for <strong>AAYU</strong> in the Extensions view</li><li>Install the extension with the purple AAYU icon</li></ul><p>If you want to install locally before publication, use the <code>.vsix</code> package in <code>vscode-aayu/</code>.</p><h2 id="_3-generate-a-new-application" tabindex="-1">3. Generate a New Application <a class="header-anchor" href="#_3-generate-a-new-application" aria-label="Permalink to &quot;3. Generate a New Application&quot;">​</a></h2><p>You can use AAYU&#39;s Native Intent Engine to scaffold a completely functioning enterprise architecture by just describing your intent in English.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aayu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Build a Hospital Management System&quot;</span></span></code></pre></div><p>This command will output:</p><ul><li><code>main.aayu</code> (The full logic, relations, and RBAC definitions)</li><li><code>views/</code> (Auto-generated UI screens)</li></ul><h2 id="_3-run-the-server" tabindex="-1">3. Run the Server <a class="header-anchor" href="#_3-run-the-server" aria-label="Permalink to &quot;3. Run the Server&quot;">​</a></h2><p>To start the server and interact with your new application:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aayu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.aayu</span></span></code></pre></div><p>Navigate to <code>http://localhost:8080</code> to see your running web application.</p><hr><h2 id="downloads-coming-soon" tabindex="-1">Downloads (Coming Soon) <a class="header-anchor" href="#downloads-coming-soon" aria-label="Permalink to &quot;Downloads (Coming Soon)&quot;">​</a></h2><p>In the upcoming weeks, AAYU will provide pre-compiled, standalone binaries built using our Rust VM runtime (<code>aayu-rs</code>).</p><ul><li>Windows Installer (<code>.exe</code>) - <strong>Coming Soon</strong></li><li>macOS Installer (<code>.dmg</code>) - <strong>Coming Soon</strong></li><li>Linux Installer (<code>.deb</code> / <code>.rpm</code>) - <strong>Coming Soon</strong></li></ul><p>Until then, the recommended installation method is via <code>pip</code>.</p>',25)])])}const g=e(n,[["render",l]]);export{u as __pageData,g as default};
